// Generated: standard font AFM metrics embedded for serverless (no fs access).
// Source: node_modules/pdfkit/js/data/*.afm
import type { readFileSync } from 'fs'

const AFM: Record<string, string> = {
  "Courier-Bold": "",
  "Courier-BoldOblique": "",
  "Courier-Oblique": "",
  "Courier": "",
  "Helvetica-Bold": "",
  "Helvetica-BoldOblique": "",
  "Helvetica-Oblique": "",
  "Helvetica": "",
  "Symbol": "",
  "Times-Bold": "",
  "Times-BoldItalic": "",
  "Times-Italic": "",
  "Times-Roman": "",
  "ZapfDingbats": "",
}

export function installStandardFontsPatch(fsMod: { readFileSync: typeof readFileSync }): void {
  const original = fsMod.readFileSync
  fsMod.readFileSync = ((p: any, ...args: any[]) => {
    if (typeof p === 'string' && p.includes('/pdfkit/js/data/') && p.endsWith('.afm')) {
      const name = p.split('/').pop()!.replace('.afm', '')
      const data = AFM[name]
      if (data !== undefined) return Buffer.from(data, 'base64').toString('utf8')
    }
    return (original as any).call(fsMod, p, ...args)
  }) as any
}
